const menu=document.querySelector('.menu'),nav=document.querySelector('#navigation');function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus();}});document.querySelector('.skip').addEventListener('click',()=>document.querySelector('#main').focus({preventScroll:true}));
// Delivery is intentionally unconfigured; never show a false success or transmit form data.
const form=document.querySelector('#contact-form');form.addEventListener('submit',e=>{e.preventDefault();const status=document.querySelector('#contact-status');status.textContent='Your inquiry has not been sent. Online message delivery is not connected yet. Your entries remain here.';status.focus();});

form.querySelector('button[type=submit]').disabled=false;
